export function transform2D(h,j,p,x,u,l){l=l||[];let n=0;for(let c=j;c<p;c+=x){const o=h[c],g=h[c+1];l[n++]=u[0]*o+u[2]*g+u[4],l[n++]=u[1]*o+u[3]*g+u[5]}return l&&l.length!=n&&(l.length=n),l}export function rotate(h,j,p,x,u,l,n){n=n||[];const c=Math.cos(u),o=Math.sin(u),g=l[0],f=l[1];let r=0;for(let i=j;i<p;i+=x){const Y=h[i]-g,X=h[i+1]-f;n[r++]=g+Y*c-X*o,n[r++]=f+Y*o+X*c;for(let k=i+2;k<i+x;++k)n[r++]=h[k]}return n&&n.length!=r&&(n.length=r),n}export function scale(h,j,p,x,u,l,n,c){c=c||[];const o=n[0],g=n[1];let f=0;for(let r=j;r<p;r+=x){const i=h[r]-o,Y=h[r+1]-g;c[f++]=o+u*i,c[f++]=g+l*Y;for(let X=r+2;X<r+x;++X)c[f++]=h[X]}return c&&c.length!=f&&(c.length=f),c}export function translate(h,j,p,x,u,l,n){n=n||[];let c=0;for(let o=j;o<p;o+=x){n[c++]=h[o]+u,n[c++]=h[o+1]+l;for(let g=o+2;g<o+x;++g)n[c++]=h[g]}return n&&n.length!=c&&(n.length=c),n}
